```cpp
template <typename N> template <typename Point>
typename Earcut<N>::Node*
Earcut<N>::insertNode(std::size_t i, const Point& pt, Node* last) {
    Node* p = nodes.construct(static_cast<N>(i),
                              util::nth<0, Point>::get(pt),
                              util::nth<1, Point>::get(pt));

    if (!last) {
        p->prev = p;
        p->next = p;

    } else {
        assert(last);
        p->next = last->next;
        p->prev = last;
        last->next->prev = p;
        last->next = p;
    }
    return p;
}

template <typename N>
void Earcut<N>::removeNode(Node* p) {
    p->next->prev = p->prev;
    p->prev->next = p->next;

    if (p->prevZ) p->prevZ->nextZ = p->nextZ;
    if (p->nextZ) p->nextZ->prevZ = p->prevZ;
}
```

`insertNode` inserts **after** `last` (pinned — inserting before breaks 130/131). Allocator is a block pool; `currentIndex` is initialised to `blockSize` so the first `construct` triggers a block allocation, and `reset` clamps block size with `std::max<std::size_t>(1, newBlockSize)`:

```cpp
template <typename T, typename Alloc = std::allocator<T>>
class ObjectPool {
public:
    ObjectPool() { }
    ObjectPool(std::size_t blockSize_) { reset(blockSize_); }
    ~ObjectPool() { clear(); }
    template <typename... Args>
    T* construct(Args&&... args) {
        if (currentIndex >= blockSize) {
            currentBlock = alloc_traits::allocate(alloc, blockSize);
            allocations.emplace_back(currentBlock);
            currentIndex = 0;
        }
        T* object = &currentBlock[currentIndex++];
        alloc_traits::construct(alloc, object, std::forward<Args>(args)...);
        return object;
    }
    void reset(std::size_t newBlockSize) {
        for (auto allocation : allocations) alloc_traits::deallocate(alloc, allocation, blockSize);
        allocations.clear();
        blockSize = std::max<std::size_t>(1, newBlockSize);
        currentBlock = nullptr;
        currentIndex = blockSize;
    }
    void clear() { reset(blockSize); }
private:
    T* currentBlock = nullptr;
    std::size_t currentIndex = 1;
    std::size_t blockSize = 1;
    std::vector<T*> allocations;
    Alloc alloc;
    typedef typename std::allocator_traits<Alloc> alloc_traits;
};
ObjectPool<Node> nodes;
```

## 5. Geometry helpers

```cpp
// check if a point lies within a convex triangle
template <typename N>
bool Earcut<N>::pointInTriangle(double ax, double ay, double bx, double by,
                                double cx, double cy, double px, double py) const {
    return (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0 &&
           (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0 &&
           (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0;
}

// signed area of a triangle
template <typename N>
double Earcut<N>::area(const Node* p, const Node* q, const Node* r) const {
    return (q->y - p->y) * (r->x - q->x) - (q->x - p->x) * (r->y - q->y);
}

// check if two points are equal
template <typename N>
bool Earcut<N>::equals(const Node* p1, const Node* p2) {
    return p1->x == p2->x && p1->y == p2->y;
}

template <typename N>
int Earcut<N>::sign(double val) {
    return (0.0 < val) - (val < 0.0);
}
```

`area` returns **negative for CCW** with this operand order — hence `if (area(a,b,c) >= 0) return false;` in `isEar` means "reflex". This orientation convention is the single most load-bearing detail; the swapped form breaks 130/131.

